"""Frozen Wave7 verification preparations; independent of later ORM changes."""
# ruff: noqa: E501

TABLES = ('verification_preparations', 'verification_current_preparations')

SCHEMA_SQL = (
    "\nCREATE TABLE verification_preparations (\n\tproduct_id UUID NOT NULL, \n\tproject_id UUID NOT NULL, \n\tbuild_id UUID NOT NULL, \n\tbuild_revision INTEGER NOT NULL, \n\trequest_id UUID NOT NULL, \n\trevision INTEGER NOT NULL, \n\towner_id UUID NOT NULL, \n\tvisibility VARCHAR(16) NOT NULL, \n\tstatus VARCHAR(16) NOT NULL, \n\tprevious_preparation_id UUID, \n\tprevious_revision INTEGER, \n\treason TEXT NOT NULL, \n\tinput_snapshot JSONB NOT NULL, \n\trequest_snapshot JSONB NOT NULL, \n\tsnapshot_sha256 VARCHAR(64) NOT NULL, \n\tsources JSONB NOT NULL, \n\trequired_source_read_set JSONB NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, id), \n\tUNIQUE (tenant_id, product_id, request_id, revision), \n\tUNIQUE (tenant_id, product_id, request_id, id, revision), \n\tUNIQUE (tenant_id, product_id, project_id, build_id, build_revision, request_id, id, revision), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id) REFERENCES builds (tenant_id, product_id, project_id, id), \n\tFOREIGN KEY(tenant_id, owner_id) REFERENCES principals (tenant_id, id), \n\tFOREIGN KEY(tenant_id, product_id, project_id, build_id, build_revision, request_id, previous_preparation_id, previous_revision) REFERENCES verification_preparations (tenant_id, product_id, project_id, build_id, build_revision, request_id, id, revision), \n\tCHECK (revision > 0 AND build_revision > 0 AND status = 'prepared'), \n\tCHECK (visibility IN ('private','product')), \n\tCHECK ((previous_preparation_id IS NULL AND previous_revision IS NULL AND revision = 1) OR (previous_preparation_id IS NOT NULL AND previous_revision IS NOT NULL AND previous_preparation_id <> id AND revision = previous_revision + 1)), \n\tCHECK (COALESCE(request_snapshot->>'status' = 'draft', false)), \n\tCHECK (COALESCE(request_snapshot->'samples' = '[]'::jsonb AND request_snapshot->'acceptances' = '[]'::jsonb AND request_snapshot->'offered_coverage' = '[]'::jsonb AND request_snapshot->'returns' = '[]'::jsonb, false)), \n\tCHECK (COALESCE(jsonb_typeof(request_snapshot->'timeline'->'request_created') = 'object', false)), \n\tCHECK (COALESCE(request_snapshot->'timeline'->'sample_ready' = 'null'::jsonb, false)), \n\tCHECK (COALESCE(request_snapshot->'timeline'->'documents_complete' = 'null'::jsonb, false)), \n\tCHECK (COALESCE(request_snapshot->'timeline'->'offered' = 'null'::jsonb, false)), \n\tCHECK (COALESCE(request_snapshot->'timeline'->'accepted' = 'null'::jsonb, false)), \n\tCHECK (COALESCE(request_snapshot->'timeline'->'promised_start' = 'null'::jsonb, false)), \n\tCHECK (COALESCE(request_snapshot->'timeline'->'actual_start' = 'null'::jsonb, false)), \n\tCHECK (COALESCE(request_snapshot->'timeline'->'preliminary_result' = 'null'::jsonb, false)), \n\tCHECK (COALESCE(request_snapshot->'timeline'->'final_result' = 'null'::jsonb, false)), \n\tCHECK (COALESCE(request_snapshot->'timeline'->'disposed' = 'null'::jsonb, false))\n)\n\n",
    'CREATE INDEX ix_verification_preparations_tenant_id ON verification_preparations (tenant_id)',
    '\nCREATE TABLE verification_current_preparations (\n\tproduct_id UUID NOT NULL, \n\trequest_id UUID NOT NULL, \n\tpreparation_id UUID NOT NULL, \n\tpreparation_revision INTEGER NOT NULL, \n\tid UUID NOT NULL, \n\ttenant_id UUID NOT NULL, \n\tcreated_at TIMESTAMP WITH TIME ZONE NOT NULL, \n\tPRIMARY KEY (id), \n\tUNIQUE (tenant_id, product_id, request_id), \n\tFOREIGN KEY(tenant_id, product_id, request_id, preparation_id, preparation_revision) REFERENCES verification_preparations (tenant_id, product_id, request_id, id, revision), \n\tCHECK (preparation_revision > 0)\n)\n\n',
    'CREATE INDEX ix_verification_current_preparations_tenant_id ON verification_current_preparations (tenant_id)',
)
